func (s *Server) authOptions(w http.ResponseWriter, r *http.Request) {
	enabled := s.boolSetting(r.Context(), "oidc.enabled", false)
	title := strings.TrimSpace(s.stringSetting(r.Context(), "general.site_title", "ai-admin"))
	if title == "" {
		title = "ai-admin"
	}
	defaultTheme := s.stringSetting(r.Context(), "ui.default_theme", "system")
	if defaultTheme != "light" && defaultTheme != "dark" && defaultTheme != "system" {
		defaultTheme = "system"
	}
	build := buildinfo.Current()
	// oidcAutoLogin tells the browser whether to try a silent (prompt=none)
	// sign-in before showing the login screen. It is only ever true while SSO
	// itself is enabled, so a stale flag cannot start a login that 404s.
	writeData(w, http.StatusOK, map[string]any{
		"localEnabled":  true,
		"oidcEnabled":   enabled,
		"oidcAutoLogin": enabled && s.boolSetting(r.Context(), "oidc.auto_login", false),
		"siteTitle":     title,
		"defaultTheme":  defaultTheme,
		"compactMode":   s.boolSetting(r.Context(), "ui.compact_mode", false),
		"version":       build.Version,
	})
}

func (s *Server) login(w http.ResponseWriter, r *http.Request) {
	var request struct {
		Username string `json:"username"`
		Password string `json:"password"`
	}
	if !decodeJSON(w, r, &request) {
		return
	}
	if strings.TrimSpace(request.Username) == "" || request.Password == "" {
		writeError(w, http.StatusBadRequest, "credentials_required", "아이디와 비밀번호를 입력해 주세요.")
		return
	}
	now := time.Now()
	remoteIP := clientIP(r)
	if allowed, retry := s.logins.allowed(remoteIP, request.Username, now); !allowed {
		w.Header().Set("Retry-After", strconv.Itoa(int(retry.Round(time.Second).Seconds())))
		writeError(w, http.StatusTooManyRequests, "login_rate_limited", "로그인 시도가 너무 많습니다. 잠시 후 다시 시도해 주세요.")
		return
	}
	if !s.logins.acquire() {
		w.Header().Set("Retry-After", "1")
		writeError(w, http.StatusServiceUnavailable, "login_busy", "로그인 처리가 혼잡합니다. 잠시 후 다시 시도해 주세요.")
		return
	}
	defer s.logins.release()
	minutes := s.intSetting(r.Context(), "security.session_minutes", 480)
	principal, token, err := s.auth.Login(r.Context(), request.Username, request.Password, remoteIP, r.UserAgent(), minutes)
	if err != nil {
		s.logins.failed(remoteIP, request.Username, now)
		s.audit(r, auth.Principal{}, "auth.login", "session", strings.TrimSpace(request.Username), "failure", map[string]any{"reason": "invalid_credentials"})
		writeError(w, http.StatusUnauthorized, "invalid_credentials", "아이디 또는 비밀번호가 올바르지 않습니다.")
		return
	}
	s.logins.succeeded(remoteIP, request.Username)
	s.setSessionCookies(w, token, principal.CSRFToken, time.Duration(minutes)*time.Minute)
	s.audit(r, principal, "auth.login", "session", "", "success", map[string]any{"source": "local"})
	writeData(w, http.StatusOK, map[string]any{"user": principal})
}

func (s *Server) me(w http.ResponseWriter, r *http.Request) {
	p := principalFrom(r.Context())
	if p.AuthMethod == "api_key" && !p.HasScope("profile:read") {
		writeError(w, http.StatusForbidden, "scope_denied", "API 키에 profile:read scope가 없습니다.")
		return
	}
	p.CSRFToken = ""
	writeData(w, http.StatusOK, map[string]any{"user": p})
}

func (s *Server) logout(w http.ResponseWriter, r *http.Request) {
	p := principalFrom(r.Context())
	if err := s.auth.RevokeSession(r.Context(), p.SessionHash); err != nil {
		writeError(w, http.StatusInternalServerError, "logout_failed", "로그아웃을 처리하지 못했습니다.")
		return
	}
	s.clearSessionCookies(w)
	s.audit(r, p, "auth.logout", "session", "", "success", nil)
	writeData(w, http.StatusOK, map[string]bool{"loggedOut": true})
}

func (s *Server) setSessionCookies(w http.ResponseWriter, token, csrf string, maxAge time.Duration) {
	secure := s.boolSetting(context.Background(), "security.cookie_secure", false)
	seconds := int(maxAge.Seconds())
	http.SetCookie(w, &http.Cookie{
		Name: auth.CookieName, Value: token, Path: "/", HttpOnly: true, Secure: secure,
		SameSite: http.SameSiteLaxMode, MaxAge: seconds,
	})
	http.SetCookie(w, &http.Cookie{
		Name: "ai_admin_csrf", Value: csrf, Path: "/", HttpOnly: false, Secure: secure,
		SameSite: http.SameSiteStrictMode, MaxAge: seconds,
	})
}

func (s *Server) clearSessionCookies(w http.ResponseWriter) {
	for _, name := range []string{auth.CookieName, "ai_admin_csrf"} {
		http.SetCookie(w, &http.Cookie{Name: name, Value: "", Path: "/", HttpOnly: name == auth.CookieName, MaxAge: -1, Expires: time.Unix(1, 0), SameSite: http.SameSiteLaxMode})
	}
}

func clientIP(r *http.Request) string {
	value := strings.TrimSpace(r.RemoteAddr)
	host, _, err := net.SplitHostPort(value)
	if err != nil {
		host = strings.Trim(value, "[]")
	}
	parsed := net.ParseIP(host)
	if parsed == nil {
		return ""
	}
	return parsed.String()
}

func csrfCookie(r *http.Request) string {
	cookie, err := r.Cookie("ai_admin_csrf")
	if err != nil {
		return ""
	}
	return cookie.Value
}

func decodeRaw(value []byte) any {
	var result any
	if len(value) == 0 || json.Unmarshal(value, &result) != nil {
		return nil
	}
	return result
}
