// storableInVarchar reports whether a PostgreSQL varchar/text column can hold
// the value. Those types cannot store a NUL byte at any length, and
// encoding/json turns "\u0000" into one, so a request carrying it is a caller
// mistake that has to be refused with the same 400 as a too-long value rather
// than reaching UPDATE and surfacing as a 500.
func storableInVarchar(value string) bool {
	return !strings.ContainsRune(value, 0)
}

