func (s *Server) recoverer(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		defer func() {
			recovered := recover()
			if recovered == nil {
				return
			}
			// A handler that deliberately abandons a partly written response
			// signals it with http.ErrAbortHandler; swallowing that here would
			// leave the caller holding a truncated body under a 200 status.
